export type SlideImage = {
  src: string;
  description: string;
};

export type DiagramKind =
  | "bst"
  | "balance"
  | "rbtree"
  | "black-height"
  | "operations"
  | "rotation"
  | "complexity";

export type Slide = {
  title: string;
  template_id: number;
  images: SlideImage[];
  texts?: string[];
  speaker_notes?: string;
  image?: string;
  /** Optional inline SVG diagram. Takes precedence over `images[0]`. */
  diagram?: DiagramKind;
  /**
   * Path to a pre-generated ElevenLabs narration MP3 served from /public.
   * Generated by `scripts/generate-audio.mjs`. When present, the voice
   * dock plays this file instead of falling back to browser TTS.
   */
  audio?: string;
};

export type Lecture = {
  title: string;
  description: string;
  slides: Slide[];
};

export type FunctionCall = {
  name: "next_slide" | "prev_slide" | "goto_slide" | "pause" | "resume";
  arguments?: Record<string, unknown>;
};

export type TranscriptEntry = {
  role: "agent" | "user";
  content: string;
  timestamp: number;
};
